import { expect, test, vi } from 'vitest';
import { middleware } from './middleware';
import { NextRequest } from 'next/server';

test('middleware adds X-Request-Id header and logs pathname', async () => {
  // Mock console.log
  const consoleSpy = vi.spyOn(console, 'log');

  // Create a mock request
  const req = new NextRequest(new URL('http://localhost:3000/test-path'));

  // Call the middleware
  const res = await middleware(req);

  // Assertions

  // Check if console.log was called with the correct pathname
  // We expect something like: [uuid] Request pathname: /test-path
  expect(consoleSpy).toHaveBeenCalledWith(expect.stringContaining('Request pathname: /test-path'));

  // Check if the response has the X-Request-Id header
  const requestId = res?.headers.get('X-Request-Id');
  expect(requestId).toBeTruthy();

  // Verify the log contains the same request ID
  expect(consoleSpy).toHaveBeenCalledWith(expect.stringContaining(`[${requestId}]`));

  // Clean up
  consoleSpy.mockRestore();
});

